<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, reactive, ref } from 'vue'
import { ElMessage } from 'element-plus'
import DataChart from '@/components/DataChart.vue'
import { cancelExperiment, createExperiment, getAudit, getExperiment, getExperiments, getSampleStatistics } from '@/api/ml'
import type { Audit, Experiment, SampleStatistics } from '@/types/ml'

const audit=ref<Audit>(), stats=ref<SampleStatistics>(), experiments=ref<Experiment[]>([]), active=ref<Experiment>(), loading=ref(false), error=ref('')
const form=reactive({name:'',model_type:'lstm',quality_profile:'strict',epochs:30,batch_size:128,learning_rate:0.003,hidden_size:16,num_layers:1,dropout:0,patience:6,seed:42})
let timer:number|undefined
const curveOption=computed(()=>({tooltip:{trigger:'axis'},legend:{data:['训练损失','验证损失']},xAxis:{type:'category',data:active.value?.training_curve.map(row=>row.epoch)??[]},yAxis:{type:'value',name:'标准化 MSE'},series:[{name:'训练损失',type:'line',showSymbol:false,data:active.value?.training_curve.map(row=>row.train_loss)??[]},{name:'验证损失',type:'line',showSymbol:false,data:active.value?.training_curve.map(row=>row.validation_loss)??[]}]}))
async function refresh(){ experiments.value=await getExperiments(); const running=experiments.value.find(row=>['queued','preparing','training','evaluating'].includes(row.status)); if(running){active.value=await getExperiment(running.id)} }
async function load(){ loading.value=true; error.value=''; try{ [audit.value,stats.value]=await Promise.all([getAudit(),getSampleStatistics(form.quality_profile)]); await refresh() }catch(e){error.value='训练数据审计加载失败，请确认后端和数据库状态。'}finally{loading.value=false} }
async function updateStats(){stats.value=await getSampleStatistics(form.quality_profile)}
async function start(){loading.value=true; try{active.value=await createExperiment({name:form.name||undefined,model_type:form.model_type,quality_profile:form.quality_profile,config:{epochs:form.epochs,batch_size:form.batch_size,learning_rate:form.learning_rate,hidden_size:form.hidden_size,num_layers:form.num_layers,dropout:form.dropout,patience:form.patience,seed:form.seed}}); ElMessage.success('真实训练任务已创建')}catch(e:any){ElMessage.error(e.response?.data?.message||'训练任务创建失败')}finally{loading.value=false}}
async function cancel(){if(active.value) active.value=await cancelExperiment(active.value.id)}
onMounted(()=>{load();timer=window.setInterval(async()=>{if(active.value&&['queued','preparing','training','evaluating'].includes(active.value.status)){active.value=await getExperiment(active.value.id);if(!['queued','preparing','training','evaluating'].includes(active.value.status))await refresh()}},1000)})
onBeforeUnmount(()=>clearInterval(timer))
</script>
<template><section v-loading="loading" class="page-stack"><div class="page-heading"><div><h2>模型训练</h2><p>真实 IBTrACS 历史时序 · 未来 6 小时 CMA 风速回测</p></div></div><el-alert title="研究边界" description="本页面执行历史最佳路径资料回测，不是实时业务预报；测试集不参与早停或超参数选择。" type="warning" :closable="false" show-icon/><el-alert v-if="error" :title="error" type="error" :closable="false"/>
<el-card shadow="never" class="data-card"><template #header><strong>训练数据审计</strong></template><div v-if="audit" class="metric-grid"><div><span>有效 CMA 风速</span><strong>{{audit.valid_cma_wind_count.toLocaleString()}}</strong></div><div><span>缺失比例</span><strong>{{(audit.missing_cma_wind_ratio*100).toFixed(1)}}%</strong></div><div><span>严格样本</span><strong>{{audit.strict_sample_count.toLocaleString()}}</strong></div><div><span>扩展样本</span><strong>{{audit.extended_sample_count.toLocaleString()}}</strong></div><div><span>17 kn 特殊编码</span><strong>{{audit.special_cma_17_count}}</strong></div><div><span>异常风速</span><strong>{{audit.abnormal_wind_count}}</strong></div></div><p class="muted-note">严格配置仅使用 CMA IFLAG 第三位 O/V；扩展配置允许 P/I，但所有输入和标签仍要求同一 SID 的严格 6 小时窗口。</p></el-card>
<el-card shadow="never" class="data-card"><template #header><strong>新建真实训练实验</strong></template><el-form label-position="top" class="training-form"><el-form-item label="实验名称"><el-input v-model="form.name" placeholder="留空自动命名"/></el-form-item><el-form-item label="模型"><el-select v-model="form.model_type"><el-option label="Persistence" value="persistence"/><el-option label="Ridge" value="ridge"/><el-option label="LSTM" value="lstm"/><el-option label="GRU" value="gru"/></el-select></el-form-item><el-form-item label="质量配置"><el-select v-model="form.quality_profile" @change="updateStats"><el-option label="严格 O/V（主实验）" value="strict"/><el-option label="扩展 O/V/I/P" value="extended"/></el-select></el-form-item><template v-if="['lstm','gru'].includes(form.model_type)"><el-form-item label="最大 Epoch"><el-input-number v-model="form.epochs" :min="1" :max="300"/></el-form-item><el-form-item label="Batch Size"><el-input-number v-model="form.batch_size" :min="8" :max="512"/></el-form-item><el-form-item label="学习率"><el-input-number v-model="form.learning_rate" :min="0.0001" :max="0.1" :step="0.0005" :precision="4"/></el-form-item><el-form-item label="隐藏维度"><el-input-number v-model="form.hidden_size" :min="4" :max="128"/></el-form-item><el-form-item label="随机种子"><el-input-number v-model="form.seed"/></el-form-item></template></el-form><div v-if="stats" class="split-strip"><span>训练 {{(stats.splits.train as any).sample_count}} / {{(stats.splits.train as any).event_count}} 个事件</span><span>验证 {{(stats.splits.validation as any).sample_count}} / {{(stats.splits.validation as any).event_count}} 个事件</span><span>测试 {{(stats.splits.test as any).sample_count}} / {{(stats.splits.test as any).event_count}} 个事件</span><span>SID 交叉：{{(stats.splits.no_sid_leakage as boolean)?'无':'有'}}</span></div><el-button type="primary" :disabled="!!active&&['queued','preparing','training','evaluating'].includes(active.status)" @click="start">开始真实训练</el-button></el-card>
<el-card v-if="active" shadow="never" class="data-card"><template #header><div class="card-header"><strong>{{active.name}}</strong><el-tag>{{active.status}}</el-tag></div></template><el-progress :percentage="Math.round(active.progress)"/><p>阶段：{{active.phase}} · Epoch {{active.current_epoch}} / {{active.max_epochs||'无需迭代'}} · 设备 {{active.device||'准备中'}}</p><el-alert v-if="active.error_message" :title="active.error_message" type="error" :closable="false"/><el-button v-if="['queued','preparing','training','evaluating'].includes(active.status)" type="danger" plain @click="cancel">终止训练</el-button><DataChart v-if="active.training_curve.length&&active.model_type!=='ridge'" :option="curveOption" label="真实训练和验证损失曲线"/></el-card></section></template>
